function carnotEfficiency(Th, Tc){ if(Th<=0) return NaN; return 1 - Tc/Th; }
function carnotWork(Qh, Th, Tc){ return Qh * carnotEfficiency(Th, Tc); }
var EXPORTS = { carnotEfficiency:carnotEfficiency, carnotWork:carnotWork };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeatEngineForgePure = EXPORTS; }
